def shortestCoverAll(nums):
    need = len(set(nums))
    cnt = {}
    have = 0
    left = 0
    best = len(nums)
    for right, x in enumerate(nums):
        cnt[x] = cnt.get(x, 0) + 1
        if cnt[x] == 1:
            have += 1
        while have == need:
            best = min(best, right - left + 1)
            y = nums[left]
            cnt[y] -= 1
            if cnt[y] == 0:
                have -= 1
            left += 1
    return best
